			/**
			 * 해당 메뉴가 이미 오픈되어 있는지 여부를 반환한다.
			 * @param psAppId
			 * @param {cpr.data.IDataRow} poRow
			 */
			function isExistTabItem(psAppId, poRow) {
			    var vcMdiCn = app.lookup("mdiCn");
			    var voItems = vcMdiCn.getTabItems();
			    
			    var vsMenuNo = poRow.getValue("MENU_NO");
			    var vsMenuNm = poRow.getValue("MENU_NM");
			    var vsMenuType = poRow.getValue("MENU_TYPE");
			    
			    
			    var flag1 = false;
			    
			    if (voItems != null && voItems.length > 0) {
			        var allreadyOpen = voItems.some(function(item) {
			            if (!item.content) return false;
			            var vsMenuInfo = item.userAttr("__menuInfo");
			            var vsTargerMenuNo = "";
			            var vsTargerMenuNm = "";
			            
			            if (!ValueUtil.isNull(vsMenuInfo)) {
			                var voMenuInfo = JSON.parse(item.userAttr("__menuInfo"));
			                vsTargerMenuNo = voMenuInfo["MENU_NO"];
			                vsTargerMenuNm = voMenuInfo["MENU_NM"];
			            }
			            
			            // 화면에서 다이렉트로 메뉴를 오픈한경우 id와 메뉴명으로 비교
			            if (vsMenuType == "DIRECT_MENU") {
			                if (item.content.app && item.content.app.id == psAppId && vsMenuNm == vsTargerMenuNm) {
			                    vcMdiCn.setSelectedTabItem(item);
			                    flag1 = true;
			                    //return true;
			                }
			            } else if (item.content.app) { // embeddedApp            
			                if (item.content.app != null && item.content.app.id == psAppId && vsMenuNo == vsTargerMenuNo) {
			                    vcMdiCn.setSelectedTabItem(item);
			                    flag1 = true;
			                    //return true;
			                }
			            } else { // embeddedPage
			                if (item.content != null && item.content.src == psAppId && vsMenuNo == vsTargerMenuNo) {
			                    vcMdiCn.setSelectedTabItem(item);
			                    flag1 = true;
			                    //return true;
			                }
			            }
			            //return false;
			        });
			        //return allreadyOpen;
			    } else {
			        //return false;
			    }
			    
			    if (flag1) {
			        //return flag1;
			        return 1;
			    }
			    
			    
			    var flag = false;
			    
			    var voLoadApps = cpr.core.Platform.INSTANCE.getAllLoadedApps();
			    for (var i = voLoadApps.length; i > 0; i--) {
			        if (psAppId == voLoadApps[i - 1].id) {
			            //vcMdiCn.setSelectedTabItem(voLoadApps[i - 1]);
			            //voLoadApps[i - 1]
			            flag = true;
			            break;
			        }
			    }
			    
			    if (flag) {
			        return 2;
			    } else {
			        return 3;
			    }
			    //return flag;
			}
			exports.isExistTabItem = isExistTabItem;

			function doFillLayoutHeigth(pcChild) {
			    
			    /**@type cpr.core.AppInstance*/
			    var childApp, voAppContainer;
			    
			    if (pcChild instanceof cpr.controls.EmbeddedApp) {
			        childApp = pcChild.getEmbeddedAppInstance();
			        voAppContainer = childApp.getContainer();
			        
			    } else {
			        voAppContainer = pcChild;
			        childApp = pcChild.getAppInstance();
			    }
			    
			    var vsFixLayout = voAppContainer.userData("fixLayout");
			    
			    if (vsFixLayout == "Y") return;
			    
			    //앱컨테이너가 버티컬 레이아웃이고 작업영역그룹이 하나이거나 해당 컨테이너의 자식컨트롤 중 fillLayout 사용자정의속성이 Y인 그룹의
			    // 높이를 화면에 꽉차게 재정의
			    var vcFillLayout;
			    var flExclusionHeight = 0;
			    var vaChildren = voAppContainer.getChildren();
			    
			    var vaFillLayout = vaChildren.filter(function(each) {
			        return "Y" == each.userAttr("fillLayout");
			    });
			    
			    var vaDisableBoxIds = voAppContainer.getChildren().filter(function(child) {
			        return child.type == "container" &&
			            (child.id != "grpSearch" && child.id != "grpHeader" && child.id != "grpFltBtns" && child.style.getClasses().indexOf("search-box") == -1 && child.visible == true);
			    });
			    
			    if (vaFillLayout.length == 1) {
			        vcFillLayout = vaFillLayout[0];
			    } else if (vaDisableBoxIds.length >= 1) {
			        vcFillLayout = vaDisableBoxIds[0];
			    } else {
			        return;
			    }
			    
			    if (vcFillLayout && voAppContainer.getLayout() instanceof cpr.controls.layouts.VerticalLayout) {
			        
			        // 업무 화면 Container는 버티컬 레이아웃
			        var vnEmbContSpacing = voAppContainer.getLayout().spacing;
			        
			        vaChildren.forEach(function(ctrl) {
			            if (ctrl.id != vcFillLayout.id) {
			                
			                // visible false 제외
			                if (ctrl.visible == false) return;
			                
			                // 플로팅 컨트롤 제외
			                if (voAppContainer.getChild(ctrl.id).isFloated()) {
			                    return;
			                }
			                
			                var voChildConst = voAppContainer.getConstraint(ctrl);
			                var vsRectHeight = ctrl.getActualRect().height;
			                var vnHeight;
			                
			                if (vsRectHeight > 0 && vsRectHeight != null && vsRectHeight != undefined) {
			                    vnHeight = ctrl.getActualRect().height;
			                } else {
			                    var vsHeight = voChildConst.height;
			                    vnHeight = vsHeight.replace("px", "");
			                }
			                
			                flExclusionHeight += vnEmbContSpacing;
			                flExclusionHeight += ValueUtil.fixNumber(vnHeight);
			                
			            }
			        });
			        
			        var vnEmbHeight = voAppContainer.getConstraint(vcFillLayout).height;
			        var vnEmbActualHeight = childApp.getActualRect().height;
			        
			        if (!vnEmbHeight) {
			            return;
			        }
			        
			        var vnEmbHeight = vnEmbHeight.replace("px", "");
			        vnEmbHeight = ValueUtil.fixNumber(vnEmbHeight);
			        
			        //보수적으로 데이터 레이아웃 높이가 800이 넘으면 기존 유지
			        if (vnEmbHeight > 800) {
			            voAppContainer.userData("fixLayout", "Y");
			            return;
			        }
			        
			        var mainHeight = app.getActualRect().height;
			        mnZoomRate
			        if (mainHeight >= 600) {
			            
			            var embHeight = voAppContainer.getConstraint(vcFillLayout).height;
			            var embActlHeight = childApp.getActualRect().height;
			            
			            if (embHeight.indexOf("calc(100%") < 0) {
			                vcFillLayout.userAttr("origin.height", embHeight);
			            }
			            
			            var poConstraint = {
			                // top + 20px, bottom margin + 10px 씩
			                height: "calc(100% - " + (flExclusionHeight + 20 + 10) + "px)"
			                
			            };
			            
			        } else {
			            
			            var vsHeightPx = "680px";
			            var vsFillLayoutOrgH = vcFillLayout.userAttr("origin.height");
			            
			            if (!ValueUtil.isNull(vsFillLayoutOrgH)) {
			                vsHeightPx = vsFillLayoutOrgH;
			            }
			            var poConstraint = {
			                height: vsHeightPx
			                /*  , minHeight: 500
			                  , autoSize: "height"*/
			            };
			        }
			        voAppContainer.updateConstraint(vcFillLayout, poConstraint);
			    }
			}
