			/**
			 * 사용자 최상위 업무에 따른 대시보드 선택 
			 * @param {Number} pnTaskWorkCd 단위 시스템 업무별 메뉴 코드
			 */
			function loadDashBoard(pnTaskWorkCd) {
			    
			    var vcEmbDash = app.lookup("embDashBoard");
			    var voDsTaskWorkDbList = app.lookup("dsTaskWorkDbList");
			    var voTargetAppId = voDsTaskWorkDbList.findFirstRow("CMMNS_CD_VALUE == '" + pnTaskWorkCd + "'");
			    var vsTargetAppId = "app/com/main/dashBoard/mainDashBoard"; // 기본
			    
			    if (voTargetAppId) {
			        var vsAppIdVal = voTargetAppId.getValue("CMMNS_CD_VALUE_NM");
			        
			        if (!ValueUtil.isNull(vsAppIdVal)) {
			            if (vsAppIdVal.indexOf(".clx") != -1) {
			                vsTargetAppId = vsAppIdVal.substring(0, vsAppIdVal.lastIndexOf(".clx"));
			            } else {
			                vsTargetAppId = vsAppIdVal;
			            }
			        }
			    }
			    // 그룹권한 적용에 따른 경찰청, 교육부 메인화면 변경    
			    var groupAuthrt = app.lookup("dmUserInfo").getValue("GROUP_AUTHRT_SE_CD");
			    if(groupAuthrt.substr(0,1) == "4"){ // 경찰청 권한      
			        vsTargetAppId =  "app/com/main/dashBoard/policeDashBoard";
			    } else if (groupAuthrt.substr(0,1) == "5") { // 교육부 권한
			        vsTargetAppId =  "app/com/main/dashBoard/eduDashBoard";
			    }
			    cpr.core.App.load(vsTargetAppId, function(loadedApp) {
			        if (loadedApp) {
			            
			            vcEmbDash.app = loadedApp;
			            // 화면 최소 크기를 지정합니다.(스크린 기준크기 1280 + 10px) 
			            vcEmbDash.app.setPreferredSize(1200, 820);
			            util.AppStack.push(vsTargetAppId);
			            
			            if (vcEmbDash.hasAppMethod("reload")) {
			                vcEmbDash.callAppMethod("reload", getSelectSysCd());
			            }
			        }
			    });
			}

