			/*
			 * MDI 폴더에서 close 이벤트 발생 시 호출.
			 * 탭 아이템을 닫을 때 발생하는 이벤트이며, 사용자가 취소할 수 있습니다.
			 */
			function onMdiCnClose( /* cpr.events.CUIEvent */ e) {
			    /** 
			     * @type cpr.controls.MDIFolder
			     */
			    var mdiCn = e.control;
			    var item = e.content;
			    
			    var menuInfo = JSON.parse(item.userAttr("__menuInfo"));
			    if (item && item.content) {
			        
			        var vcItemApp = item.content.getEmbeddedAppInstance();
			        
			        // mdi 닫기시 처리로직 개선예정
			        //        if (util.isAppModified(vcItemApp, "CRM")) {
			        //            e.preventDefault();
			        //            return false;
			        //        }
			        item.content.removeAllUserAttr();
			        item.content.removeAllEventListeners();
			    }
			    
			    /* 첫 아이템을 제외한 나머지 탭 아이템이 닫혔을 때 첫 아이템 선택 */
			    var vaLastTabItems = _.reject(mdiCn.getTabItems(), function(each) {
			        return each == item;
			    });
			    
			    if (vaLastTabItems.length > 1) {
			        
			        if (closeAction != "x") {
			            mdiCn.setSelectedTabItem(vaLastTabItems[vaLastTabItems.length - 1]);
			        }
			        
			    } else {
			        
			        mdiCn.setSelectedTabItem(vaLastTabItems[0]);
			        
			        var btnDfItem = app.lookup("btnDfItem");
			        btnDfItem.style.addClass("cl-selected");
			        
			        closeAction = "o";
			    }
			    
			    // 아이템 닫기시 앱스텍도 동시제거
			    util.AppStack.pop(menuInfo["URL_ADDR"], menuInfo);
			}

