			/*
			 * 버튼(btnZoom)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnZoomClick( /* cpr.events.CMouseEvent */ e) {
			    /**@type cpr.controls.Button*/
			    var btnZoom = e.control;
			    
			    var floatCtrl = null;
			    app.getContainer().getChildren().forEach(function(/*cpr.controls.Container*/ each) {
			        if (each.id == "grpFloat") {
			            if (each.isFloated()) {
			                floatCtrl = each;
			            }
			        }
			    });
			    
			    var vbZoomed = btnZoom.style.hasClass("cl-selected");
			    
			    if (vbZoomed) {
			        
			        zoomOutConent();
			        
			        if (floatCtrl) {
			            app.getContainer().floatControl(floatCtrl, zoomOutFloatConst);
			        }
			        
			    } else {
			        
			        zoomInContent();
			        
			        if (floatCtrl) {
			            app.getContainer().floatControl(floatCtrl, zoomInFloatConst);
			        }
			    }
			    
			}

