			/*
			 * 버튼(btnToggle)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnToggleClick(e) {
			    var btnToggle = e.control;
			    
			    var vbChecked = true;
			    
			    if (btnToggle.style.hasClass("cl-selected")) {
			        btnToggle.style.removeClass("cl-selected");
			        collapseSideMenu();
			        vbChecked = false;
			    } else {
			        btnToggle.style.addClass("cl-selected");
			        expandSideMenu();
			        vbChecked = true;
			    }
			    
			    transitionEnd();
			    
			    localStorage.setItem("isToggle", vbChecked);
			}

