			// 메뉴 선택시 또는 탭 변경시 메뉴의 CRUD 권한을 dmUserInfo 에 넣음.
			function addMenuAuth(menuNo) {
			    var dsMenuList = app.lookup("dsMenuList");
			    var dmUserInfo = app.lookup("dmUserInfo");
			    
			    dmUserInfo.setValue("INQ_BUTTON_USE_YN", "");
			    dmUserInfo.setValue("DTL_INQ_BUTTON_USE_YN", "");
			    dmUserInfo.setValue("INITL_BUTTON_USE_YN", "");
			    dmUserInfo.setValue("REG_BUTTON_USE_YN", "");
			    dmUserInfo.setValue("MDFCN_BUTTON_USE_YN", "");
			    dmUserInfo.setValue("DEL_BUTTON_USE_YN", "");
			    dmUserInfo.setValue("MNG_BUTTON_USE_YN", "");
			    
			    for (var i=0; i < dsMenuList.getRowCount(); i++) {
			        var menu = dsMenuList.getRowData(i);
			        if (menu["MENU_NO"] == menuNo) {
			            dmUserInfo.setValue("INQ_BUTTON_USE_YN", menu["INQ_BUTTON_USE_YN"]);
			            dmUserInfo.setValue("DTL_INQ_BUTTON_USE_YN", menu["DTL_INQ_BUTTON_USE_YN"]);
			            dmUserInfo.setValue("INITL_BUTTON_USE_YN", menu["INITL_BUTTON_USE_YN"]);
			            dmUserInfo.setValue("REG_BUTTON_USE_YN", menu["REG_BUTTON_USE_YN"]);
			            dmUserInfo.setValue("MDFCN_BUTTON_USE_YN", menu["MDFCN_BUTTON_USE_YN"]);
			            dmUserInfo.setValue("DEL_BUTTON_USE_YN", menu["DEL_BUTTON_USE_YN"]);
			            dmUserInfo.setValue("MNG_BUTTON_USE_YN", menu["MNG_BUTTON_USE_YN"]);
			            break;
			        }
			    }
			    
			    //console.log("dmUserInfo", dmUserInfo.getDatas());
			}

